        target = max(1, min(total, int(round(ratio * total))))
        seqs, cmax = _schedule(inst, s)
        per_machine = []
        if cmax > 0:
            center = rng.uniform(0.0, float(cmax))
            w = max(1.0, ratio * cmax)
            for _ in range(60):
                lo, hi = center - w / 2.0, center + w / 2.0
                per_machine = []
                count = 0
                for m, seq in enumerate(seqs):
