                    pairs = []
                    for x in range(len(inside)):
                        for y in range(x + 1, len(inside)):
                            pairs.append((inside[x], inside[y]))
                    if pairs:
                        rng.shuffle(pairs)
                        per_machine.append((m, pairs))
                        count += len(pairs)
                if 2 * count >= target or w >= 2.0 * cmax:
                    break
                w *= self.growth
        rng.shuffle(per_machine)
        free = set()
        idx = 0
        progress = True
        while len(free) < target and progress:
            progress = False
            for (m, pairs) in per_machine:
